<script setup lang="ts">
import {ref} from 'vue';
import {api} from '../services/api';
import {requirePrivacyReview} from '../services/privacyGuard';
import {useAccountStore} from '../stores/account';
const props=defineProps<{caseId:string;inventory:any}>(),emit=defineEmits<{changed:[]}>(),account=useAccountStore(),file=ref<File|null>(null),consent=ref(false),error=ref(''),message=ref(''),busy=ref(false);
async function upload(){error.value='';busy.value=true;try{if(!file.value)throw Error('请选择附件');await requirePrivacyReview('',[file.value],'',consent.value);const form=new FormData();form.append('file',file.value);form.append('consent','true');const result=await api(`/api/v1/cases/${props.caseId}/attachments`,{method:'POST',body:form});message.value=result.status==='parsed'?'附件已取得，旧任务确认已失效；请重新分析并核对。':'附件未能读取，请换清晰文件后重试。';file.value=null;consent.value=false;emit('changed')}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function retry(){if(!window.confirm('仅对已确认上传的通知与附件重新分析，保留历史及任务状态；同意继续？'))return;busy.value=true;try{await api(`/api/v1/cases/${props.caseId}/analysis/retry`,{method:'POST',body:JSON.stringify({consent:true})});message.value='已重新分析，请重新核对任务和日期。';emit('changed')}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><section v-if="inventory?.items?.length||account.signedIn" class="surface-card" aria-label="通知附件完整度"><h2>通知附件</h2><p v-if="inventory?.missing_count" class="notice notice--warning">还缺 {{inventory.missing_count}} 项附件或读取失败，分析暂不完整。请补充上传，不会自动访问附件链接。</p><p v-else-if="inventory?.items?.length">引用附件已取得，仍需核对内容；不代表全部资格已识别。</p><p v-else>未发现明确附件引用。请对照原通知：若另有附件，请补充上传；当前结果只覆盖已取得来源。</p><article v-for="(item,index) in inventory?.items||[]" :key="index"><b>{{item.title}} · {{item.state==='obtained'?'已取得':item.state==='failed'?'读取失败':'待补充'}}</b><blockquote>{{item.quote}}</blockquote><p>{{item.warning}}</p><a v-if="item.url" :href="item.url" target="_blank" rel="noopener noreferrer">查看原附件链接（可能需要登录）</a></article><template v-if="account.signedIn&&!caseId.startsWith('demo-')"><label>补充通知附件<input type="file" @change="file=($event.target as HTMLInputElement).files?.[0]||null;consent=false"></label><label class="consent-row"><input v-model="consent" type="checkbox">已核对附件隐私，确认上传到当前事项</label><button class="button button--secondary" :disabled="busy||!file||!consent" @click="upload">确认上传附件</button><button class="button button--primary" :disabled="busy" @click="retry">用补充附件重新分析</button></template><p v-if="error" role="alert" class="notice notice--danger">{{error}}</p><p v-if="message" role="status">{{message}}</p></section></template>
<style scoped>blockquote{margin:8px 0;overflow-wrap:anywhere}label{display:block;margin:8px 0}input[type=file]{max-width:100%}</style>
